mapper.select:


    inner join sys_user u on u.user_name = tlabeltemplate.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tlabeltemplate.del_flag = '0'
    and tlabeltemplate.name like concat('%', #{name}, '%')
    and tlabeltemplate.label_type = #{labelType}
    and tlabeltemplate.label_width = #{labelWidth}
    and tlabeltemplate.label_height = #{labelHeight}
    and tlabeltemplate.image_width = #{imageWidth}
    and tlabeltemplate.image_height = #{imageHeight}
    and tlabeltemplate.object_width = #{objectWidth}
    and tlabeltemplate.object_height = #{objectHeight}
    and tlabeltemplate.status = #{status}


${params.dataScope}
